INSERT INTO reviews (id, reservation_id, user_id, hotel_id, rating, content)
VALUES
    ('40000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000001', 5, '강남에서 여기만한 곳이 없어요! 시설 너무 깨끗하고 선생님들이 너무 친절하셔서 안심하고 맡겼습니다.'),
    ('40000000-0000-4000-8000-000000000002', '30000000-0000-4000-8000-000000000002', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000001', 4, '24시간 케어해주시는 점이 제일 마음에 들어요. 사진도 자주 보내주시고 서비스 만족합니다.'),
    ('40000000-0000-4000-8000-000000000003', '30000000-0000-4000-8000-000000000003', 'b0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000002', 5, '청담동에 이런 프라이빗한 펫 호텔이 있는지 몰랐어요. 공간이 정말 고급스럽습니다.'),
    ('40000000-0000-4000-8000-000000000004', '30000000-0000-4000-8000-000000000004', 'b0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000002', 5, '픽업 서비스 덕분에 바쁜 평일에도 편하게 맡길 수 있었어요.'),
    ('40000000-0000-4000-8000-000000000005', '30000000-0000-4000-8000-000000000005', 'b0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000003', 5, '대형견도 편하게 받아주는 곳이 드문데 여기는 공간이 넓어서 좋았어요.'),
    ('40000000-0000-4000-8000-000000000006', '30000000-0000-4000-8000-000000000006', 'b0000000-0000-4000-8000-000000000006', 'd0000000-0000-4000-8000-000000000003', 4, '미용까지 같이 맡길 수 있어서 시간이 절약됐습니다.'),
    ('40000000-0000-4000-8000-000000000007', '30000000-0000-4000-8000-000000000007', 'b0000000-0000-4000-8000-000000000007', 'd0000000-0000-4000-8000-000000000004', 5, '건강검진까지 챙겨주셔서 안심이 됐어요. 발렛파킹도 편했습니다.'),
    ('40000000-0000-4000-8000-000000000008', '30000000-0000-4000-8000-000000000008', 'b0000000-0000-4000-8000-000000000008', 'd0000000-0000-4000-8000-000000000004', 4, '서초에서 접근성 좋고 시설도 깔끔해요.')
INSERT INTO hotels (id, partner_id, name, address, lat, lng, description, status)
VALUES
    ('d0000000-0000-4000-8000-000000000005', 'a0000000-0000-4000-8000-000000000001', '강아지월드 홍대점', '서울 마포구 홍대동', 37.556542, 126.923688, '홍대 번화가 근처에서 자율체크인이 가능한 소형견 특화 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000001', '냥이하우스 잠실', '서울 송파구 잠실동', 37.513294, 127.100107, '24시간 상주 케어와 픽업 서비스를 제공하는 잠실 고양이 전문 호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000001', '펫스위트 여의도', '서울 영등포구 여의도동', 37.521637, 126.924191, '자율체크인, 24시간 케어, 픽업까지 원스톱으로 제공하는 여의도 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000001', '도그팰리스 판교', '경기 성남시 분당구 판교동', 37.394726, 127.111436, '미용과 픽업 서비스를 함께 제공하는 판교 테크노밸리 인근 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000001', '캣앤독 리조트 일산', '경기 고양시 일산동구', 37.658776, 126.771793, '자율체크인과 24시간 상주 케어를 갖춘 일산 대형 펫 리조트입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000001', '펫프렌즈 수원', '경기 수원시 영통구', 37.259835, 127.043505, '자율체크인, 미용, 픽업까지 모두 지원하는 수원 영통구 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000001', '로얄펫텔 분당', '경기 성남시 분당구', 37.385206, 127.123456, '24시간 케어와 미용 서비스를 함께 제공하는 분당 프리미엄 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000012', 'a0000000-0000-4000-8000-000000000001', '해피펫스테이 부천', '경기 부천시', 37.503359, 126.766248, '자율체크인, 24시간 케어, 미용, 픽업을 모두 갖춘 부천 종합 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000001', '펫하우스 인천 송도', '인천 연수구 송도동', 37.381949, 126.646626, '픽업 서비스가 강점인 송도국제도시 인근 펫호텔입니다.', 'ACTIVE'),
    ('d0000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000001', '우리동네펫텔 용인', '경기 용인시 수지구', 37.322838, 127.097696, '자율체크인, 24시간 케어, 픽업을 제공하는 용인 수지구 동네 펫호텔입니다.', 'ACTIVE')
