INSERT INTO reviews (id, reservation_id, user_id, hotel_id, rating, content)
VALUES
    ('40000000-0000-4000-8000-000000000009', '30000000-0000-4000-8000-000000000009', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000005', 5, '홍대 놀러 나온 김에 맡겼는데 자율체크인이라 시간 맞추기 편했어요.'),
    ('40000000-0000-4000-8000-00000000000a', '30000000-0000-4000-8000-00000000000a', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000005', 4, '소형견 위주라 그런지 다른 강아지들이랑도 잘 어울렸어요.'),
    ('40000000-0000-4000-8000-00000000000b', '30000000-0000-4000-8000-00000000000b', 'b0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000006', 5, '고양이 전문이라 그런지 스트레스 덜 받는 것 같았어요. 픽업도 편했습니다.'),
    ('40000000-0000-4000-8000-00000000000c', '30000000-0000-4000-8000-00000000000c', 'b0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000006', 5, '24시간 케어해주셔서 밤에도 안심하고 맡길 수 있었어요.'),
    ('40000000-0000-4000-8000-00000000000d', '30000000-0000-4000-8000-00000000000d', 'b0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000007', 4, '여의도 출장 중에 맡겼는데 픽업까지 해주셔서 정말 편했습니다.'),
    ('40000000-0000-4000-8000-00000000000e', '30000000-0000-4000-8000-00000000000e', 'b0000000-0000-4000-8000-000000000006', 'd0000000-0000-4000-8000-000000000007', 5, '스위트룸이 넓고 쾌적해서 아이가 편하게 지낸 것 같아요.'),
    ('40000000-0000-4000-8000-00000000000f', '30000000-0000-4000-8000-00000000000f', 'b0000000-0000-4000-8000-000000000007', 'd0000000-0000-4000-8000-000000000008', 4, '판교 근처라 접근성이 좋고 미용까지 같이 해결했어요.'),
    ('40000000-0000-4000-8000-000000000010', '30000000-0000-4000-8000-000000000010', 'b0000000-0000-4000-8000-000000000008', 'd0000000-0000-4000-8000-000000000008', 5, '프라이빗룸이라 다른 강아지들과 안 마주쳐서 예민한 아이도 편해했어요.'),
    ('40000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000011', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000009', 5, '일산에서 이 정도 규모의 리조트는 처음 봤어요. 공간이 정말 넓습니다.'),
    ('40000000-0000-4000-8000-000000000012', '30000000-0000-4000-8000-000000000012', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000009', 4, '대형견룸이 따로 있어서 좋았어요. 24시간 케어도 만족스러웠습니다.'),
    ('40000000-0000-4000-8000-000000000013', '30000000-0000-4000-8000-000000000013', 'b0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000010', 5, '수원 영통구에서 접근성 좋고 미용까지 한번에 해결했어요.'),
    ('40000000-0000-4000-8000-000000000014', '30000000-0000-4000-8000-000000000014', 'b0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000010', 4, '픽업 서비스 덕분에 차 없이도 편하게 맡겼어요.'),
    ('40000000-0000-4000-8000-000000000015', '30000000-0000-4000-8000-000000000015', 'b0000000-0000-4000-8000-000000000005', 'd0000000-0000-4000-8000-000000000011', 5, '분당에서 이 정도 프리미엄 시설은 드문 것 같아요. 매우 만족합니다.'),
    ('40000000-0000-4000-8000-000000000016', '30000000-0000-4000-8000-000000000016', 'b0000000-0000-4000-8000-000000000006', 'd0000000-0000-4000-8000-000000000011', 5, '미용까지 같이 맡겼는데 손질이 꼼꼼했어요.'),
    ('40000000-0000-4000-8000-000000000017', '30000000-0000-4000-8000-000000000017', 'b0000000-0000-4000-8000-000000000007', 'd0000000-0000-4000-8000-000000000012', 4, '자율체크인부터 픽업까지 다 되니까 정말 편했습니다.'),
    ('40000000-0000-4000-8000-000000000018', '30000000-0000-4000-8000-000000000018', 'b0000000-0000-4000-8000-000000000008', 'd0000000-0000-4000-8000-000000000012', 5, '부천에서 이렇게 다 갖춘 펫호텔은 처음이에요. 자주 이용할 것 같아요.'),
    ('40000000-0000-4000-8000-000000000019', '30000000-0000-4000-8000-000000000019', 'b0000000-0000-4000-8000-000000000001', 'd0000000-0000-4000-8000-000000000013', 4, '송도에서 픽업까지 해주셔서 정말 편하게 맡길 수 있었어요.'),
    ('40000000-0000-4000-8000-000000000020', '30000000-0000-4000-8000-000000000020', 'b0000000-0000-4000-8000-000000000002', 'd0000000-0000-4000-8000-000000000013', 5, '스위트룸이 넓어서 아이가 편하게 지낸 것 같습니다.'),
    ('40000000-0000-4000-8000-000000000021', '30000000-0000-4000-8000-000000000021', 'b0000000-0000-4000-8000-000000000003', 'd0000000-0000-4000-8000-000000000014', 4, '동네에 있어서 접근성이 정말 좋고 자율체크인이라 편했어요.'),
    ('40000000-0000-4000-8000-000000000022', '30000000-0000-4000-8000-000000000022', 'b0000000-0000-4000-8000-000000000004', 'd0000000-0000-4000-8000-000000000014', 5, '용인 수지구 주민이라 자주 이용하는데 항상 만족스러워요.')
