-- 개발/테스트용 시드 데이터. partner 관리 기능이 아직 없어서 호텔 FK를 만족시키기 위한
-- 임시 partner 1건과, 호텔 노출 확인용 더미 예약/리뷰까지 포함한다.
-- 모든 id를 고정값으로 박아두고 ON CONFLICT (id) DO NOTHING을 써서 재시작해도 중복 삽입되지 않는다.

-- 1. partner (임시)
VALUES ('a0000000-0000-4000-8000-000000000001', 'partner-test@petitel.com', 'N/A', '펫티텔 테스트 파트너', '123-45-67890', 'APPROVED')
ON CONFLICT (id) DO NOTHING;

-- 2. 리뷰 작성용 더미 유저 8명
ON CONFLICT (id) DO NOTHING;

-- 3. 위 유저들의 반려동물 (예약에 최소 1마리씩 필요)
ON CONFLICT (id) DO NOTHING;

-- 4. 호텔 4곳 (프론트 mock 데이터와 동일한 구성)
ON CONFLICT (id) DO NOTHING;

-- 5. 호텔 대표 이미지 (Unsplash의 실제 반려동물/숙소 사진 사용 — 만화 일러스트 대신 실사 느낌)
-- image_url은 재선정될 수 있어서 DO UPDATE로: 이미 존재하는 호텔이어도 재시작 시 최신 사진으로 갱신된다.
ON CONFLICT (id) DO UPDATE SET image_url = EXCLUDED.image_url;

-- 6. 편의시설 마스터 + 호텔별 매핑
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (hotel_id, facility_id) DO NOTHING;

-- 7. 객실
ON CONFLICT (id) DO NOTHING;

-- 8. 리뷰 근거용 완료된 더미 예약 + 반려동물 연결
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (reservation_id, pet_id) DO NOTHING;

-- 9. 리뷰
ON CONFLICT (id) DO NOTHING;

-- 10. 추가 호텔 10곳 (기존 test partner/reviewer/pet 재사용)
ON CONFLICT (id) DO NOTHING;

-- 실제 강아지/고양이·숙소 사진(Unsplash)으로 호텔 컨셉에 맞춰 하나씩 배정.
ON CONFLICT (id) DO UPDATE SET image_url = EXCLUDED.image_url;

ON CONFLICT (hotel_id, facility_id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- 기존 8명의 리뷰어/반려동물을 순환 재사용해서 리뷰 근거용 예약을 만든다.
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (reservation_id, pet_id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- 11. 호텔 상세 캐러셀용 추가 이미지 (호텔당 총 3장 노출)
ON CONFLICT (id) DO UPDATE SET image_url = EXCLUDED.image_url;
